"""Wire ``on_incoming_message`` / ``modify_incoming_message`` before storage."""

from __future__ import annotations

from typing import cast

from rasa.core.channels.channel import UserMessage
from rasa.core.channels.constants import (
    USER_CONVERSATION_SESSION_END,
    USER_CONVERSATION_SESSION_START,
    USER_CONVERSATION_SILENCE_TIMEOUT,
)
from rasa.mantle.hooks.constants import (
    DISCARDED_EVENT_METADATA_KEY,
    POINT_INCOMING_MESSAGE,
    UTTER_INCOMING_MESSAGE_REJECTED,
)
from rasa.mantle.hooks.exceptions import HookExecutionError, HookRejection
from rasa.mantle.hooks.payloads import ChannelInfo, IncomingMessagePayload
from rasa.mantle.hooks.registry import HookRegistry
from rasa.mantle.hooks.runner import run_modify, run_observers
from rasa.shared.core.events import UserUttered
from rasa.shared.core.trackers import DialogueStateTracker

# Channel-emitted bootstrap / lifecycle markers — not real user text.
_SYSTEM_INCOMING_MESSAGE_TEXTS = frozenset(
    {
        USER_CONVERSATION_SESSION_START,
        USER_CONVERSATION_SESSION_END,
        USER_CONVERSATION_SILENCE_TIMEOUT,
    }
)


def strip_reserved_incoming_metadata(message: UserMessage) -> None:
    """Remove engine-owned keys from client-supplied message metadata."""
    metadata = message.metadata
    if not metadata or DISCARDED_EVENT_METADATA_KEY not in metadata:
        return
    message.metadata = {
        key: value
        for key, value in metadata.items()
        if key != DISCARDED_EVENT_METADATA_KEY
    }


def mark_logged_user_utterance_discarded(
    tracker: DialogueStateTracker,
    message: UserMessage,
) -> bool:
    """Stamp the utterance logged for *message*, if it was actually stored.

    Returns ``False`` when the inbound message was not logged (for example a
    terminated conversation), so callers do not mark a prior utterance.
    """
    if tracker.terminated:
        return False

    utterance = tracker.get_last_event_for(UserUttered)
    if not isinstance(utterance, UserUttered):
        return False

    if message.message_id is not None:
        if utterance.message_id != message.message_id:
            return False
    elif utterance.text != (message.text or ""):
        return False

    utterance.metadata = {
        **dict(utterance.metadata or {}),
        DISCARDED_EVENT_METADATA_KEY: True,
    }
    return True


async def apply_incoming_message_hooks(
    registry: HookRegistry,
    message: UserMessage,
) -> str | None:
    """Run observe/modify incoming-message hooks before user text is stored.

    Returns ``None`` when the engine should process the (possibly rewritten)
    text. When the message must be discarded, returns the response template
    name that the framework should send to the user. Unexpected failures use
    the packaged default template.

    Identity comes from the inbound ``UserMessage`` — this point runs before
    ``MessageTurnContext`` is established. Always strips a client-spoofed
    ``discarded`` metadata key first. System conversation markers
    (``/session_start``, ``/session_end``, ``/silence_timeout``) skip hooks
    entirely so channel-driven lifecycle signals cannot be vetoed or rewritten.
    Empty ``sender_id`` still runs hooks so security modifiers cannot be
    bypassed by omitting the sender.
    """
    strip_reserved_incoming_metadata(message)

    if (message.text or "") in _SYSTEM_INCOMING_MESSAGE_TEXTS:
        return None

    if (
        not registry.observers(POINT_INCOMING_MESSAGE)
        and registry.modifier(POINT_INCOMING_MESSAGE) is None
    ):
        return None

    payload = IncomingMessagePayload(
        sender_id=message.sender_id or "",
        text=message.text or "",
        message_id=message.message_id,
        channel=ChannelInfo(
            name=message.input_channel,
            metadata=dict(message.metadata or {}),
        ),
    )

    run_observers(registry, POINT_INCOMING_MESSAGE, payload)
    try:
        result = await run_modify(registry, POINT_INCOMING_MESSAGE, payload)
    except HookExecutionError:
        return UTTER_INCOMING_MESSAGE_REJECTED

    if isinstance(result.control_flow, HookRejection):
        return result.control_flow.response_message or UTTER_INCOMING_MESSAGE_REJECTED

    modified = cast(IncomingMessagePayload, result.payload)
    message.text = modified.text
    return None
